SELECT GET_JSON_OBJECT(event_properties, house_id) AS id_house, id_user, GET_JSON_OBJECT(event_properties, search_id) AS id_search, UPPER(business_context) AS business_context, up_platform AS platform, CASE WHEN up_platform IN ('android', 'ios') THEN 'app' WHEN up_platform IN ('web_desktop', 'web_mobile') THEN 'web' ELSE 'N/A' END AS platform_grouped, CASE WHEN up_platform IN ('android', 'ios', 'web_mobile') THEN 'mobile' WHEN up_platform IN ('web_desktop') THEN 'desktop' ELSE 'N/A' END AS device_type, city AS user_city, region AS user_region, country AS user_country, GET_JSON_OBJECT(event_properties, city) AS house_city, GET_JSON_OBJECT(event_properties, macro_region) AS house_macro_region, GET_JSON_OBJECT(event_properties, state) AS house_state, GET_JSON_OBJECT(event_properties, country) AS house_country, GET_JSON_OBJECT(event_properties, from_route) AS lpv_from_route, GET_JSON_OBJECT(event_properties, valor_total) AS rent_total_value, GET_JSON_OBJECT(event_properties, valor_venda) AS sale_value, ts_event, CAST(ts_event AS DATE) AS dt_event, DATE_TRUNC('WEEK', ts_event) AS ts_event_week, DATE_TRUNC('MONTH', ts_event) AS ts_event_month, DATE_TRUNC('QUARTER', ts_event) AS ts_event_quarter, year, month, day FROM datalake_amplitude_clean.170698_listing_page_viewed_events WHERE MAKE_DATE(year, month, day) BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_7 AS days_past_7) * -1) AND CAST('{end_date}' AS DATE) AND UPPER(business_context) IN ('RENT', 'SALE')